CREATE TABLE IF NOT EXISTS institutional_data_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, institution_id uuid NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'open', created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,institution_id));
CREATE TABLE IF NOT EXISTS data_room_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES institutional_data_rooms(id) ON DELETE CASCADE, request_type text NOT NULL, title text NOT NULL, description text, required_evidence text, status text NOT NULL DEFAULT 'open', priority text NOT NULL DEFAULT 'normal', requested_by text NOT NULL, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_room_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES institutional_data_rooms(id) ON DELETE CASCADE, question text NOT NULL, answer text, status text NOT NULL DEFAULT 'open', asked_by text NOT NULL, answered_by text, answered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_room_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES institutional_data_rooms(id) ON DELETE CASCADE, action text NOT NULL, actor_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());